    "question": "《中论》的核心思想是什么？",
    "answer": "《中论》以八不中道为总纲，破斥一切自性见，显示缘起性空的中道实相。核心命题是众因缘生法我说即是空——一切法因缘和合、无有自性故空；空非断灭，即缘起故有假名；不落空有二边即是中道。全论由破因缘品到观邪见品，层层扫荡执见。",
