    "answer": "六祖临终付嘱三十六对法：明与暗、阴与阳、有与无、色与空、动与静、清与浊等三十六组对立范畴。教人\"出没即离两边\"——说话时不要落在一端，要即两边而离两边。如人问\"有\"，答以“无”破之；问“无”，答以\"有\"破之。三十六对法是教学人破除二元对立的善巧方便：你执着哪一端，就从对面来破。终极目的是超越一切对立，回归中道实相。此法后来成为禅宗接引学人的基本手法。",
