    "answer": "临济四料简是接引学人的四种方法：一、夺人不夺境——破学人对\"我\"的执着，保留境界。二、夺境不夺人——破学人对\"境\"的执着，保留主体。三、人境俱夺——主体客体一并破除，直显空性。四、人境俱不夺——悟后境界，人境各住本位，即相离相。四料简是临济根据学人不同的执着偏重，对病施药：你执人我则夺人，你执境则夺境，你两者都执则俱夺，你两者都不执则俱不夺。看似复杂，核心只在\"破执着\"三字。",
