    "answer": "是的。《金刚经》云\"凡所有相，皆是虚妄。若见诸相非相，即见如来。\"佛的三十二相、八十种好，也是因缘所生、无有自性，故是虚妄。但\"虚妄\"不是\"不存在\"，而是\"无实自性\"。真正的如来不是有相的佛——\"若以色见我，以音声求我，是人行邪道，不能见如来\"。如来者，无所从来亦无所去——是法身、是自性、是那个无形无相的觉性。所以执着佛相求佛，恰恰背离了佛；见相非相，方见真佛。",
