    "id": "faq-872",
    "question": "什么是\"执事废理\"和\"执理废事\"？",
    "answer": "执事废理：只做形式上的修行——念佛、持咒、诵经、打坐——但不明白为什么要修、修的是什么，着在事相上。执理废事：只研究理论——谈空说有、讲禅论道——但不肯真实修行，落在口头禅上。二者皆偏。禅宗主张理事圆融：理须顿悟，事须渐修；悟理不废事修，事修不违理悟。如六祖\"本来无一物\"是理，\"时时勤拂拭\"是事——悟后保任，拂而无拂，方为中道。",
