    "answer": "直指人心是禅宗的根本教法——不借经教、不立文字、不涉阶次，直接指向你当下的心。达摩来华，不携一卷经，只传一心：你那个能听、能看、能觉知的，就是佛心——不必外求。直指不是告诉你一个道理，是逼你回光返照——你问\"如何是佛？\"禅师不答道理，或答\"干屎橛\"、或便打、或便喝——截断你的思维，逼你看那个能问的。直指人心，见性成佛——这是禅宗八字的纲宗。",
