    "question": "什么是\"三玄三要\"？",
    "answer": "临济宗三玄三要：每一句言语中须具三玄——体中玄、句中玄、玄中玄；每一玄中须具三要——不立言句、不落言句、不离言句。三玄三要是临济对\"活句\"的分析：一句中含三层意——表层（句中玄）、深层（体中玄）、超越层（玄中玄）；每层又有三个要点——不立、不落、不离。看似复杂，核心只在\"说而不着\"——说了但不落在说的相上。会得三玄三要，则一切言句皆是活句；会不得，则一切言句皆是死句。",
