    "answer": "话头是参禅时提撕的公案语句——如“无”字、\"谁\"字、\"万法归一，一归何处\"等。话头的选择：一、须是无意味的——不能通过思维找到答案，否则成了知识问答。二、须是祖师公案中的——有传承、有勘验。三、须与学人根机相应——妄想多用“无”字斩断，疑情多用\"谁\"字逼拶。选定后不可频换——今日参“无”，明日参\"谁\"，终无入手处。只抱住一个话头死参，行住坐卧不离，疑情自然发起。话头是敲门砖——门开即弃，不可执着。",
