    "answer": "过去心已灭——你能找回来吗？未来心未生——你能预先得到吗？现在心不住——刚说\"现在\"已成过去。三心了不可得，说明心没有实体——它只是念念生灭的相续，如流水般不曾停留。你找心，找不到；不找，它一直在。不可得不是没有心，是心无实体可得。达摩教慧可\"将心来与汝安\"，慧可\"觅心了不可得\"——正是此意。了不可得处，即是安心处；不可得处，即是自性显处。",
