    "question": "什么是\"禅宗无门关\"？",
    "answer": "《无门关》是宋代无门慧开所辑48则公案集。书名\"无门\"有两层含义：一、以“无”字为参禅之门——赵州“无”字是第一则公案。二、禅宗之门是无门之门——没有固定的方法可循，须各自参究。无门慧开云\"参禅须透祖师关，妙悟要穷心路绝。祖关不透，心路不绝，如何是透祖师关？只这一个无字，乃宗门一关也。\"——无字就是关，透得过无字，即是透祖师关。48则公案从无字开始，层层递进，是参禅入门的最佳教材。",
