    "answer": "\"老婆禅\"不是老太太修的禅——\"老婆\"是\"老婆心切\"的简称，指禅师接引学人时如老太婆般苦口婆心、反复叮咛。禅宗本以\"直指\"为尚，不尚多说。但有些禅师悲心深切，怕学人不悟，反复开示、层层剖析——这就是老婆禅。黄檗打临济三度，大愚说\"黄檗老婆心切\"——打就是老婆心切，因为打是为了令临济悟道。老婆禅虽不似机锋峻烈，但有其价值——对中下根人，老婆禅更亲切、更易入。但过度老婆则成葛藤——说多了反而遮蔽了直指。",
