    "question": "什么是\"四谛\"？",
    "answer": "四谛是原始佛教的根本教义：苦谛（世间是苦）、集谛（苦的原因是贪爱）、灭谛（苦可以灭）、道谛（灭苦的方法是八正道）。四谛是\"知苦、断集、慕灭、修道\"——从认识苦到灭苦的完整路径。禅宗对四谛的态度：不否定四谛，但超越四谛。六祖\"烦恼即菩提\"——苦谛即集谛即灭谛即道谛，四谛不二。迷时见苦可灭、有道可修；悟时苦本空、集本空、灭本空、道本空——如《心经》\"无苦集灭道\"。不是没有四谛，是四谛当体即空——空处即是实相。",
