    "answer": "般若是智慧——照见实相的根本智。方便般若是善巧——以般若为体，以方便为用，度众生时的善巧方法。般若是\"知\"，方便是\"行\"——知万法皆空，而行六度万行度众生。如观世音\"以何身得度即现何身\"——知众生本空（般若），而现种种身度众生（方便）。禅宗的棒喝、机锋、转语都是方便般若——以般若为体，以各种善巧为用。没有般若的方便是世俗智巧——度不了人；没有方便的般若是枯木慧——度不了众生。般若与方便如鸟双翼，缺一不可。",
