    "answer": "永嘉玄觉参访六祖慧能于曹溪，与六祖对机，一宿之间大悟，故世称\"一宿觉\"。六祖印可曰\"何方速疾至此，可留一宿\"。此为禅宗\"言下顿悟\"的典型。但永嘉大师之顿悟非无因之悟——其早年精研天台止观，已有深厚教观基础，故参六祖一言即悟。",
