    "answer": "可以，而且相得益彰。《心铭》是理——阐明无心绝观的见地；《坐禅仪》是行——详述坐禅调心的方法。以《心铭》之见地指导坐禅，则坐禅不落死寂；以《坐禅仪》之方法落实无心，则无心不成空谈。法融说“一切莫顾，安心无处”是理，宗赜说“一切善恶都莫思量”是行，二者合参，理事圆融。",
    "relatedBooks": ["xinming","zuochanyi"]
