    "question": "曹山“异类中行”的四种异类分别是什么？",
    "answer": "四种异类：一者往来异类——未知有自己，一切言语声色是非；二者菩萨同异类——先明自己后入生死异类中摄他，不舍生死类，自利利他；三者沙门异类——知有本分事，丧尽凡圣因果，触处得自由，不入诸圣报位，亦云披毛戴角；四者宗门中异类——作家语不偏不正，不有不无，呼为异类中虚，直须虚一位全无的的也。",
