    "question": "博山说的“做工夫”是什么意思？和平时说的“下功夫”有何不同？",
    "answer": "“做工夫”是禅门术语，特指提起话头、参究公案的实地修行。与世间“下功夫”的本质区别在于：世间功夫是心有所求、日进一寸的积累；做工夫却是提起一则话头（如“万法归一，一归何处”），发起疑情，行住坐卧单单究这一句，做到“行不知行、坐不知坐”，通身只是一个疑团。博山强调做工夫要“紧、正、绵密、融豁”，一日要见一日工夫——不是坐等开悟，而是如觅失物般穷追不舍。",
