    "answer": "因为动境人厌、静境人贪——行人一向处喧闹场中，一与静境相应，如食饴蜜、如倦人喜睡，不知不觉便沉溺进去。博山警告：外道使身心断灭化为顽石，正是从静境而入；枯之又枯、寂之又寂，堕于无知，与木石何异？正路是“于大事中求其静相了不可得”——不是为了静而坐，是为了明生死大事而参。玄沙更斥“凝心敛念、摄事归空”为落空亡外道、魂不散的死人。静境不是道，只是做工夫的余波。",
