    "question": "什么是“识神”？为什么说认识神为佛事“做外道奴也不得”？",
    "answer": "识神即能知能觉、能动能静的分别灵知——扬眉瞬目、见闻觉知的那个“能”者。博山说最怕把它当作佛事：误认灵知为真性，修行便全盘错路，故云“若把识神当事，做外道奴也不得”。勘验之法玄沙早已示明：认昭昭灵灵是汝真实，为何瞌睡时它就不见、做不得主？生死到来更如何？识神是生死根、妄想缘气，认贼作子，万劫缠缚。参“念佛是谁”正是要勘破这能知觉者背后的机关。",
