    "id": "faq-1598",
    "question": "“悬崖撒手，自肯承当；绝后再苏，欺君不得”如何理解？",
    "answer": "这是古德形容大悟的两段关口。悬崖撒手：把一切依靠——道理、境界、身心、能所——全体放下，如临崖撒手，自肯承当大事，更无一物可把。绝后再苏：疑团逼到命根断处、大死一番之后，绝处复苏，方是真实悟境——至此欺君不得：自他俱瞒不过，悟与不悟、浅与深，明眼人一勘便知。博山引此示人：若命根不断，全是生灭心；若命根断去而不知转身吐气，唤作堕身死汉。大死与大活，必须连成一片。",
