    "question": "博山自述“打失布袋”自谓大悟，为何见了宝方和尚反而“始具惭愧”？",
    "answer": "这是博山修行自传中最紧要的一段。他参“没踪迹”句，一日阅《传灯录》见赵州“三千里外逢人始得”，忽然打失布袋，如放下千斤担子，自谓大悟。但去见宝方和尚，被一勘验，如方木逗圆孔——方圆不合，始知从前悟处只是解路，惭愧无比。宝方更“不肯”他，以偈勉之。博山由此得出全书最重要的教训：悟后若不见大善知识，纵得安逸，终是未了。连宗匠尚须经历“自谓悟—被勘破—真悟”的进程，后人稍有境界便自称证悟，正是博山痛警的狂病。",
