    "question": "参禅会走火入魔吗？博山如何看《楞严经》五十种阴魔？",
    "answer": "答六雪关主问时，博山细剖《楞严》五十种魔事，结论只有一句：总以妄想为根。着即成魔，计则名外——魔不从外来，全是自心妄想凝结、乘隙而现。对治之法不是与魔对抗（那是雪上加霜），而是“但全身入理，不待遣，不待护，妄想念尽，则魔业自尽”。引思大禅师“十方诸佛被我一口吞尽”，佛祖位中留渠不住，邪魔外种其奈尔何。要点：不作圣解，名善境界；若作圣解，即受群邪。见光见华不以为奇，魔自无门可入。",
