    "id": "faq-1603",
    "question": "“不是一番寒彻骨，怎得梅花扑鼻香”出自哪里？",
    "answer": "出自黄檗希运禅师偈：“尘劳迥脱事非常，紧把绳头作一场；不是一番寒彻骨，怎得梅花扑鼻香。”博山在《警语》中特引此偈，说“此语最亲切！若将此偈时时警策，工夫自然做得上”。世人常引后两句励志，却常忘了前两句的分量：“尘劳迥脱”是透脱生死，“紧把绳头”是死命做工夫——正是在寒彻骨的紧把中，才有梅花的香气。博山又引百里程途为喻：说得乡里事业再了了分明，不走终不到家。",
