    "question": "博山为学人开示参“无”字、“万法归一”、“念佛是谁”等不同话头，该选哪一个？",
    "answer": "博山在卷下“示禅人参公案警语”中分别开示：参无字要“有无俱剿绝，直探骊龙珠”，如四面火起唯求一线生路；参万法归一要“竖起眉毛，如大火聚，生与同生，死与同死”；参念佛公案要知“一句阿弥陀，如珠投浊水”，念至妄止处再究“依稀识得娘生面，展似眉毛作么生”；看父母未生前则“单提句话头，不堕诸方便”。选话头的原则：对机即是好——疑情发得起的那个就是你的本参。选定之后贵专一：“只在一则公案上用心，不可一切公案上作解会。”",
