    "question": "为什么悟后还必须见善知识？“悟后不见大善知识，终是未了”",
    "answer": "博山以自身为例：他自谓大悟后见宝方，方知未了；得宝方“不肯”两字，受用不尽。原因有三：一、悟处可能有解路混入，如方木逗圆孔，须宗师勘验方能拣别；二、法身病微细——坐在法身量边、耽着受用、隐隐有物，自己最难自查，须善知识磕着痛处；三、悟后转身吐气、入廛垂手的向上一路，须人抽钉拔楔。故博山反复叮咛：悟后只须见人，若不肯见人，皆唤作自欺底汉。“不肯见人，为执己见，禅中大病无过此者。”",
