    "id": "faq-1607",
    "question": "“参禅须铁汉，毋论期与限”——现代人有工作家庭，如何用博山的方法？",
    "answer": "铁汉之心可学，铁汉之形不必泥。博山方法对现代人的转译：一、警觉为本——每日提醒自己何事为重、时不待人，把“切”字用在工作与修学上，一日要见一日工夫；二、话头随身——行住坐卧、着衣吃饭里都可提“念佛是谁”，不必拘于坐香；三、以病为药——博山痛陈的种种禅病（将心待悟、求人说破、偷心取巧、得少为足）正是现代人学习修行的通病自检表；四、知非便舍——纵然行在错处，肯一念知非便是进步的基本。修行不在形仪猛利，在心念真切。",
