    "answer": "唐代圭峰宗密（780-841）为其编纂的百卷禅藏《禅源诸诠集》写的总序，四卷约一万六千字。中唐禅门诸宗并立互相攻击——江西、荷泽、北秀、牛头、石头等各立门户，\"以经论为干戈\"。宗密以华严宗师兼荷泽禅传人的双重身份，判禅为三宗、教为三种，一一配对相证，把一代佛法会归一味。裴休赞为\"未曾有也\"。它是禅宗史上第一部系统的判教著作，读懂它就握住了理解整个唐代禅宗格局的钥匙。",
    "relatedBooks": ["chanyuan_zhuquanjiduxu"]
