    "id": "faq-1609",
    "question": "\"禅源\"两个字是什么意思？",
    "answer": "禅，是梵语禅那的简称，翻为思惟修、静虑，是定慧的通称；源，是一切众生本觉真性，也叫佛性、心地。此性是禅的本源，所以叫禅源。宗密特别辨析：不是离开真性另有一个禅的实体——迷真合尘叫散乱，背尘合真叫禅定；直接论本性，则非真非妄、无定无乱，连\"禅\"字都安不上。这个真性还有许多名字：万法之源叫法性，迷悟之源叫如来藏，万德之源叫佛性，万行之源叫心地——名虽多，体是一个。",
    "relatedBooks": ["chanyuan_zhuquanjiduxu"]
