    "question": "达摩\"默传心印\"是怎么回事？为什么到荷泽又明说了？",
    "answer": "宗密记述早期传法规程：达摩以壁观教人安心，学人绝诸缘后自见\"了了自知、言不可及\"，师便印可\"只此是自性清净心\"；若不契，只遮诸非令再观察，绝口不先说破\"知\"字，直待他自己证到才印证——这叫默传心印，六代相传都是如此。到荷泽神会时，各宗竞起、机缘不契，又怕宗旨断绝，才明言\"知之一字众妙之门\"。默传时代以袈裟为信物；显传之后言说除疑、经论为证。一个是逼你自己见到，一个是直接告诉你——时代不同，手段不同，所指是同一个。",
