    "question": "\"先顿悟后渐修\"和\"渐修功成豁然顿悟\"矛盾吗？",
    "answer": "不矛盾，宗密分判得极细：渐修功成豁然顿悟，说的是证悟（亲证本来）；先须顿悟方可渐修，说的是解悟（见地先立）。如华严\"初发心时即成正觉\"是解悟，之后三贤十圣次第修证。还有顿悟顿修的上上根（一念不生前后际断，如牛头法融）；若远推宿世，则唯渐无顿——今生的顿，是多生渐修熏发出来的。宗密给的最美比喻：日光顿出，霜露渐消；孩子顿生，志气渐立。未悟而修非真修，悟后不修习气不除。",
