    "answer": "凡夫十重顺流而下：本有本觉真心→未遇善友法尔不觉→不觉故念起→念起故有能见→有见故根身世界妄现→不知是自心所现执为实有（法执）→执实故分自他（我执）→执身为我故贪顺嗔违（三毒）→造善恶业→业系受六道报。每一步都是上一步的自然后果，如多米诺骨牌。悟后十重逆流而上：遇善知识→发悲智愿→修五行→菩提心显→知性无悭→六度双亡我法→色自在→心自在→一念相应离念→始本不二成佛。迷从细到粗，悟从粗到细——粗障易遣浅智能翻，细惑难除深智方断。",
