    "question": "\"经是佛语，禅是佛意\"——禅教一致论对今天学佛有什么用？",
    "answer": "宗密看到的两病今天更严重：只研究经论的把修行变成学问（说食数宝），只讲究体验的把佛法变成个人感觉（盲修瞎练）。禅教一致的意思是：经论是地图，禅修是行路——没有地图的行走容易迷路，不行路的地图永远到不了目的地。他的方法论很实用：参究得个入处，要用经文印证（佛言量）；读经读懂了，要在心地上检验（现量）。三量勘契——佛语、亲证、义理三处相符才算数。执则字字疮疣，通则文文妙药。",
