    "question": "什么是\"三量勘契\"？参禅为什么还要拿经论来印？",
    "answer": "三量是印度量论的三个知识来源：比量（推理，如见烟知火）、现量（亲证现见）、佛言量（圣教为标准）。宗密指出三种偏病：只凭佛语不自参究是泛信，对自己没益处；只凭自见不受经印，焉知邪正——外道也自以为亲证真理；只用推理没有圣教和亲证，无从推起。三量勘同方为决定。这等于给修行立了验收标准：你的体验（现量）+ 道理通顺（比量）+ 与佛说一致（佛言量），三票通过才承当，缺一不可。",
