    "answer": "僧肇引《中观》“物从因缘故不有，缘起故不无”。若有若真有，有自常有岂待缘而后有？譬彼真无无自常无岂待缘而后无？若有不能自有待缘而后有故知有非真有，有非真有故不可谓之有。夫无则湛然不动可谓之无，万物若无则不应起，起而非无以明缘起故不无。以缘合则有缘离则无，故万物非有非无不真空也。",
    "relatedBooks": ["zhaolun"]
