    "answer": "玄沙师备（835-908），福州闽县人，俗姓谢，少为渔父，世称“谢三郎”。三十岁弃钓出家，嗣法雪峰义存，与雪峰名为师徒、实为道友。闽王王审知请为安国禅院开山，赐“宗一大师”号。其门下罗汉桂琛传清凉文益，文益开出法眼宗——故玄沙为法眼宗法脉之先导，雪峰一系遂为云门、法眼两宗共同源头。",
