    "answer": "玄沙师备所立接人纲宗三句：第一句“且自承当，现成具足”——信有真常流注，开方便门，但成平等法，明前不明后；第二句“回因就果，转位投机”——不著平常一如之理，生杀自在，顿超三界之佛性；第三句“知有大智性相之本”——明阴洞阳，廓周法界，入慈定之门，大用现前。三句与四轮五位相配，为玄沙绵密宗风之完整体系。",
