    "answer": "玄沙垂语：诸方老宿尽道接物利生，患盲者拈槌竖拂他不见，患聋者语言三昧他不闻，患痖者教他说又说不得——此三种病人如何接得？若接不得，佛法无灵验。此语勘尽一切接人手段：施设皆对有眼耳口者而设。后云门以拄杖挃僧、唤前喝破，一僧当下有省；地藏桂琛则以“桂琛现有眼耳口”翻转话头。",
