    "id": "faq-2157",
    "question": "圆悟克勤禅师是谁？",
    "answer": "圆悟克勤（1063-1135），北宋临济宗杨岐派，五祖法演之嗣法弟子。以《碧岩录》闻名于世，门下出大慧宗杲开看话禅一派。圆悟之评唱以“活句”与“死句”为纲宗：活句不落言诠直指人心，死句拘于文字死于句下。其两大评唱著作《碧岩录》与《击节录》为宋元禅宗评唱之双璧。",
