    "question": "雪峰义存禅师的三木毬是什么意思？",
    "answer": "雪峰凡见僧来参，便辊三个木毬示之。一日玄沙来，三个一时辊出，沙便作偃倒势。师曰：寻常用几个？沙云：三即一，一即三。又一日师辊出木毬，玄沙遂捉来安旧处。三木毬为雪峰道场独特接引方式——三毬喻三界、喻三身、喻三句。玄沙云'三即一一即三'示三一不二，捉来安旧处示用毕还源。雪峰以此勘验学人能否直下承当。",
