    "answer": "雪峰云'世界阔一尺，古镜阔一尺；世界阔一丈，古镜阔一丈'——古镜喻心，心含摄世界，世界随心显现。玄沙指火炉问阔多少，雪峰答似古镜阔，玄沙评其脚跟未点地——落在道理会。雪峰答住持事烦，不辩不争，亦是作家本色。古镜喻佛性本明，世界有多大佛性就有多大，非道理可量。",
