    "answer": "密庵一生七镇名山：一、衢州西乌巨山干明禅院（乾道三年八月一日受请）；二、衢州大中祥符禅寺；三、建康府蒋山太平兴国禅寺；四、常州褒忠显报华藏禅寺；五、临安府径山兴圣万寿禅寺；六、临安府景德灵隐禅寺；七、明州太白名山天童景德禅寺。七处皆江南名刹，道满天下。径山、灵隐、天童为南宋禅宗五山之首，密庵能七镇名山，可见其在南宋禅宗之地位。",
