    "answer": "禅教会通是紫柏真可禅师的核心教理主张——以禅宗直指人心为根本，以唯识教理为解门，以净土念佛为归趣。禅是佛心教是佛语净是佛行——三者本是一佛之全体不可割裂。紫柏以《阿赖识四分略解》以唯识解禅示禅教会通之典范。禅教会通非混滥——须以禅悟为根本以教理为解门以净土为归趣。紫柏不以释迦压孔老不以内典废子史，于佛法中不以宗压教不以教压宗——此是禅教会通之真旨。",
