    "answer": "煆昏散是紫柏真可禅师的独特工夫——煆炼昏沉散乱。紫柏著《天池山煆昏散道场说》：原未煆昏散之椎轮三世诸佛迭相授受者也。第在用之何如耳。用之果善消昏散于刹那扶止观于大寂。昏沉与散乱是参禅两大病：昏沉则心神暗昧散乱则心神外驰。须以决志逼拶煆炼之如天池山煆昏散道场以决志之火煆炼身心令昏散消落方有悟分。煆昏散非止非观——须以决志逼拶如以火煆金。",
