    "id": "faq-2211",
    "question": "紫柏真可禅师的三教一心是什么意思？",
    "answer": "紫柏《题三教图》云：我得仲尼之心而窥六经，得伯阳之心而达二篇，得佛心而始了自心。虽然佛不得我心不能说法，伯阳不得我心二篇奚作，仲尼不得我心则不能集大成也。三教一心——得仲尼之心方能窥六经，得伯阳之心方能达二篇，得佛心方能了自心。三教皆归于自心：佛不得我心不能说法，伯阳不得我心二篇奚作，仲尼不得我心则不能集大成。三教一心非混滥——须以佛心为了自心之根本。",
