    "answer": "万历三十一年（1603）发生妖书案，紫柏真可因牵连入狱，圆寂于狱中。据《东厂缉访妖书底簿》载：王之祯令校尉将达观带到西司房当厅问说你是箇高僧如何不在深山修行缘何来京城中交结士夫干预公事。有达观回说明公说的是。初二日王之祯问达观你是那裡人为何造作妖书。达观回说贫僧是苏州府吴江县人自幼出家于万历元年来京受圣上无量之恩那有此事苍苍在上若有一字虚言万劫堕地狱。钱谦益序称紫柏拚幻有之躯息清流之祸——以慈愿戒力住世舍身护法。妖书案是明代政治大案紫柏因此殉道诚明代佛教之金刚栋梁。",
