    "question": "《人天眼目》和《碧岩录》有什么区别？",
    "answer": "《碧岩录》是圆悟克勤禅师对雪窦重显禅师一百则颂古的评唱，以颂古为中心，重在评唱公案。《人天眼目》是晦岩智昭禅师编纂的禅宗纲宗集，系统整理五家核心教法，重在纲宗语句。《碧岩录》重在评唱，《人天眼目》重在纲宗——前者以公案颂古为体，后者以五家纲宗为体。二书皆为禅宗重要文献，但体例和重点不同。",
    "relatedBooks": ["renyantianmu"]
