    "question": "惠洪（洪觉范）禅师是谁？",
    "answer": "惠洪（1071-1128），字觉范，号寂音尊者，瑞州（今江西高安）人。俗姓喻，少时为云庵真净克文禅师法嗣，属临济宗黄龙派。惠洪天资极高，博通内外典籍，以文章名世，与苏轼、黄庭坚等交游。其著述宏富，除林间录外，尚有禅林僧宝传、冷斋夜话、石门文字禅等。谢逸序云：洪觉范得自在三昧于云庵老人，故能游戏翰墨场中，呻吟謦咳，皆成文章。",
