    "question": "《楞伽阿跋多罗宝经》是一部什么经？",
    "answer": "《楞伽阿跋多罗宝经》四卷，刘宋元嘉年间天竺三藏求那跋陀罗于丹阳译出。楞伽指锡兰山（今斯里兰卡），阿跋多罗意为入——此经为佛入楞伽山所说法。全经四卷皆题一切佛语心品，佛答大慧菩萨百八问，广说五法三自性八识二无我如来藏自心现量等义，以佛语心为宗。是禅宗印心之根本经典。",
    "relatedBooks": ["lengqiejing"]
