    "question": "什么是如来藏？",
    "answer": "如来藏者，自性清净客尘所染。佛告大慧：如来藏自性清净转三十二相入於一切众生身中。如大价宝垢衣所缠。如来之藏常住不变亦复如是。而阴界入垢衣所缠贪欲恚痴不实妄想尘劳所污。如来藏自性清净本在一切众生身中，但为阴界入垢衣所缠贪欲恚痴不实妄想尘劳所污——此是如来藏思想之核心。",
