    "answer": "自觉圣智者，离言说相离妄想相。佛告大慧：云何自觉圣智？谓一切法自性不生离自性相无生无灭本来寂静自性涅槃。自觉圣智即是一切法自性不生离自性相无生无灭本来寂静自性涅槃——此是楞伽经自觉圣智之教。",
    "relatedBooks": ["lengqiejing"]
