    "question": "《楞伽经》为什么文字简古难读？",
    "answer": "苏轼序云：楞伽义辄幽渺文字简古。读者或不能句而况遗文以得义忘义以了心者乎？此其所以寂寥於世几废而仅存也。楞伽经文字简古幽渺，句读困难，故寂寥於世几废而仅存。求那跋陀罗译经文辞简古，与后世译经风格不同——此是楞伽经文字简古难读之原因。",
    "relatedBooks": ["lengqiejing"]
