    "answer": "沙弥受戒仪轨包括：行者请得度牒呈本师、选日剃度隔宿剃头留方寸、设戒师高座引请闍梨作梵闍梨、剃头偈（善哉大丈夫能了世无常弃俗趣泥洹希有难思议）、落发偈（毁形守志节割爱辞所亲出家弘圣道誓度一切人）、披袈裟偈（大哉解脱服无相福田衣披奉如来戒广度诸众生）、受三归五戒、受沙弥十戒（不杀生不偷盗不淫欲不妄语不饮酒不花髻璎珞香油涂身不歌舞作唱故往观听不坐卧高广大床不非时食不捉金银钱宝）、戒师教诫、作梵闍梨回向。",
