    "answer": "僧问赵州：“承闻和尚亲见南泉，是否？”赵州答：“镇州出大萝卜头。”问佛法传承，答地方土产。赵州打破学人对名利声望、师承门第的知见罗网，随拈一物皆是真性，截断思量分别，使学人当体了悟。",
