    "answer": "僧问赵州：“万法归一，一归何处？”赵州答：“我在青州作得一领布衫，重七斤。”万法虽可归于一理（一心），若执着于这个“一”，便成死水。赵州拈出青州布衫重七斤，一把将死水搅活，教人连“一”亦彻底放下。",
