    "answer": "僧问云门：“如何是法身？”云门答：“六不收。”六指六根、六尘、六识。自性法身超越眼耳鼻舌身意与色声香味触法，非六识所能分别测量，故称六不收，展示了法身廓周法界的绝待超越性。",
