    "answer": "三圣问雪峰：“透网金鳞以何为食？”雪峰云：“待汝出网来向汝道。”三圣云：“一千五百人善知识，话头也不识。”雪峰云：“老僧住持事繁。”透网金鳞喻彻底透脱名教的大解脱人。二尊宿旗鼓相当，互勘机锋，精彩无比。",
