    "question": "《楞严经》中佛陀开示的“四种清净明诲”包含哪些？为何是成佛基石？",
    "answer": "四种清净明诲为：不淫、不杀、不盗、不妄语。佛告阿难：淫心不除，尘不可出，修定如蒸沙作饭；杀心不除，必落神道；盗心不除，必落邪道；大妄语心不除，必堕阿鼻。此四戒为戒体根本，若戒基不立，修禅定必招魔障。",
