    "question": "什么是《楞严经》中的“五十阴魔”？五阴分别对应哪些魔境？",
    "answer": "五十阴魔是修禅定行者在突破色、受、想、行、识五阴时所遭遇的五十种身心幻境与邪见偏差。色阴十魔多关身心境界变异；受阴十魔多涉悲狂喜慢等情绪极端；想阴十魔多起贪求神通神异；行阴十魔多生偏枯外道哲学见解；识阴十魔多认冥谛或断灭虚无。",
