    "answer": "玄沙师备（835-908）是雪峰义存的上首法嗣。他居玄沙山三十年，以“秘密金刚体”、“玄沙三句”开示学人，座下出罗汉桂琛，再传清凉文益开出法眼宗。玄沙是法眼宗乃至五代南方禅宗的核心法脉先驱。",
