    "answer": "玄沙痛斥当时学人将能知能觉、昭昭灵灵的分别妄识当成佛性（“认贼为子”）。他指出真正的佛性是亘古不变、湛然寂照的“秘密金刚体”，不生不灭、无相无名，唯有绝断知解分别方能亲证。",
