    "question": "《首楞严三昧经》所宣说之“首楞严三昧”（健行三昧）为何被称为一切百千三昧之王？",
    "answer": "‘首楞严’意为一切事究竟坚固。得此三昧者，能统摄一切三昧大用，不动本体而能遍应十方；示现受生、出家、成道、降魔、涅槃，乃至示现声闻、缘觉、外道身而常在正定。此乃诸佛菩萨大机大用、游戏神通之究竟宝藏，亦是禅宗见性后‘大机大用’的经典宗源。",
