    "question": "《解深密经》作为唯识学根本经典，为何对禅宗明心见性具有不可替代的理论印证价值？",
    "answer": "本经甚深开显阿陀那识（阿赖耶识）、分别所缘与胜义无自性性。禅宗所参‘父母未生前本来面目’，正是穿透前六识与第七末那识我执，直探阿陀那识深底；经云‘阿陀那识甚深细，一切种子如瀑流，我于凡愚不开演，恐彼分别执为我’，精确印证了参禅必须打破最后无明窠臼方能大悟之理。",
