    "question": "世亲菩萨《唯识三十论》如何阐释“万法唯识”？禅宗开悟在唯识学上如何定位？",
    "answer": "三十论以三十首偈颂系统阐明八识心王、心所与三能变理论。证明外境无非内识变现，‘由假说我法，有种种相转，彼依识所变’。禅宗之大彻大悟，在唯识学上即是‘转识成智’——转第八阿赖耶识为大圆镜智，转第七末那识为平等性智，转第六意识为妙观察智，转前五识为成所作智。",
