    "answer": "世亲菩萨针对小乘与外道执着外境实有之难问，以梦中无实物而见物、翳眼见空华、业力不同见水为脓河等精辟譬喻，严密论证外境非实，唯是业力内识变现。令学者彻底息灭向外驰求之妄心，归向自心觉照。",
