    "answer": "论中严密论证：前灭后生、刹那不住的意识无法持种受报，唯有甚深微细、相续不断的阿赖耶识能摄持善恶业种，遇缘成熟感得三界果报。解开千古业力受报之谜，令行者明了‘因果报应丝毫不爽，而自性本体本自解脱’。",
