    "answer": "步骤有四：一观四大幻身——地水火风各离，妄身何在？二观六尘缘影——色声香味触法消散，妄心何在？三观四大妄心俱灭——谁知幻灭？即是清净圆觉！四知幻即离，不作方便；离幻即觉，亦无渐次。直下契入如如不动之广大圆觉妙心。",
