    "answer": "‘五法’（名、相、妄想、正智、如如）：名相妄想为世间生灭，正智如如为出世真如；‘三自性’破除遍计执；‘八识’明了万法唯心；‘二无我’断除生死根源。达摩以之印心，令学者既具金刚利剑之直指顿悟，又具如来经教之圆满教证，免堕狂妄盲修之险坑。",
