    "question": "《坐禅用心记》如何告诫坐禅者面对“昏沉与掉举”两大障难？",
    "answer": "昏沉来时，当张大双目、挺拔脊梁，将心意系于鼻端或发际，策发警醒；掉举散乱来时，当放下外缘、收摄心神于脐下丹田，数息安住。昏散俱离，湛然常寂。",
    "relatedQa": "koan-65",
