    "answer": "大师以古镜为喻，直宣曹洞正脉历代单传之无上心印。宝镜朗照，形影互呈，物来即现而不留痕。教示弟子善加护持此不生不灭之本觉心体，莫向外驰求，善护自心即是报佛深恩。",
