    "answer": "本书系统剖析五家家风：临济之三玄三要、四宾主、四料简（峻烈雷轰）；曹洞之偏正五位、君臣宝镜（绵密细致）；沩仰之九十六圆相（温润方圆）；云门之三句顾鉴掣（孤危耸峻）；法眼之六相十玄（简练圆融）。令学者一览人天眼目，通晓宗门纲要。",
