    "question": "《人天眼目》中如何解释临济宗“四料简”（夺人不夺境、夺境不夺人、人境两俱夺、人境俱不夺）接引学人的妙用？",
    "answer": "‘夺人不夺境’破除学人主观执着，保留客境以验其变；‘夺境不夺人’扫除外在尘境攀缘，直显主体能知自性；‘人境两俱夺’截断凡圣情识，逼至绝境大死一番；‘人境俱不夺’绝后苏生，红尘闹市任运腾腾，展现大机大用。",
