    "answer": "论中揭示根本烦恼乃无明所生之妄执：贪着顺境、嗔恚逆境、愚痴暗昧不达实相。修禅者观烦恼如梦幻泡影，当体即空，不随不制，烦恼当下转为菩提智用。",
