    "question": "《唯识三十论》中“此诸识转变，分别所分别，由此彼皆无，故一切唯识”揭示了什么根本原理？",
    "answer": "此偈乃唯识学之纲宗：一切现象界皆是八识内变之虚妄显现，能分别的主体（见分）与所分别的客体（相分）皆依识而转，并无心外独立之实我实法。悟透此点，即能息灭二元对立之妄想。",
