    "question": "世亲菩萨在《唯识三十论》末后五颂中如何描述唯识修道之“入真见道”境地？",
    "answer": "行者修唯识观，至加行位满，彻底远离能取所取两边分别，证得‘若时于所缘，智都无所得，尔时住唯识，离二取相故’。此时直契无分别正智，与真如法界冥合一体，与禅宗言下大悟、顿见本来完全同体。",
