    "question": "《唯识二十论》如何回应“若外境无实，为何大众能同时同地见同一事物（如共见一城）”之难问？",
    "answer": "世亲菩萨以‘地狱众生共见狱卒铜狗’为喻：众人以同类共业所感，阿赖耶识中种子成熟显现相似之相分，非外境有实体。证明时空与共见皆是共业所变，为行者破除对物质世界实有性之执着。",
