    "question": "《解深密经·分别瑜伽品》中佛陀如何阐释“奢摩他（止）”与“毗钵舍那（观）”之唯识实修？",
    "answer": "佛告慈氏菩萨：心缘于自心所显现之影像而住，名为奢摩他；于此影像审谛观察、推求简择其实相，名为毗钵舍那。明示所观一切境皆是自心影像，止观不离自心，是为大乘最上乘止观法门。",
