    "question": "《解深密经》中“胜义谛相”（微细甚深、离言说、绝戏论、超度一切寻思）对指导参禅有何意义？",
    "answer": "胜义实相超越一切思维逻辑与言语概念。凡夫以寻思分别计度佛法，如同捕风捉影。本经指示学者唯有放下情思知解，以清净无分别心直下体认，方契实际理地。",
