    "question": "《宝性论》中所说如来藏之“常、乐、我、净”涅槃四德，与凡夫外道之我相有何根本不同？",
    "answer": "凡夫外道之‘我’乃妄执五蕴为实有主宰（神我、灵魂）；如来藏之‘大我’乃自性彻底离一切妄染、法界一如之自在真我。‘真常、真乐、真我、真净’乃佛性圆满自具之究竟性德，绝非生死造作之虚妄相。",
