    "question": "《宝性论》如何阐述佛性之“在缠”与“出缠”？",
    "answer": "在凡夫位名‘在缠如来藏’，佛性隐没于烦恼杂染之中而自性清净无损；在圣位经修证断惑显露名‘出缠法身’。在缠出缠，体无二致，体现了‘众生即佛、平等不二’的大乘极则法门。",
