    "answer": "因为得首楞严三昧之菩萨已彻见万法实相，深知魔与佛性空无二。菩萨不厌魔境，不著佛相，以无碍智慧方便借魔之逼恼显发甚深佛法，转逆缘为解脱胜资粮，显发不二法门之大机大用。",
