    "answer": "看话禅以‘提撕疑团’截断意根思量，默照只管打坐以‘身心脱落’直证当下本来。二者手段虽有‘峻烈逼拶’与‘澄然凝住’之别，极处完全同归——皆是教人死尽偷心、坐断妄念、当下见性成佛。",
