    "question": "《松岭宝训》中莲花生大士如何开示“修法时不可被外境魔障所转”？",
    "answer": "莲师开示：当贪嗔痴或恐怖魔相生起时，当知皆是自心妄念之投影。若向外执着驱魔，魔转增盛；若能向内反观魔心本空，明了魔即自心，心外无魔，魔境当下化为清净法界。",
