    "question": "《西藏度亡经》中为何强调“投生中阴时当关闭胎门”？禅修者当如何观照？",
    "answer": "中阴身受业力牵引见男女交会而生贪嗔爱染，即将入胎受生。经中开示当生起坚固正念：观男女父母皆如幻如化、皆是本尊法身；或以大空性观照‘能贪所贪二俱空寂’，当下截断受胎因缘，往生净土或顿证法身。",
