    "answer": "经中告诫：刺目强光乃诸佛自性大智慧光明，因众生久处无明常觉畏惧退缩；而柔和暗淡之光乃六道生死业力之诱惑。中阴身当生大信心猛利投向强光，即得解脱；若贪恋柔和业光，则必堕入六道轮回。",
