    "question": "《阿瓦陀塔之歌》中“我非心智、非理智、非心识，我非地水火风，我是不可分割的纯粹湿婆（自性）”如何打破身心认同？",
    "answer": "达塔特雷亚以彻底的否定法（Neti Neti，非此非彼）剥离一切客尘属性。肉体是尘土，心智是流动波纹，而那恒常观照身心生灭者才是真我。此种大无畏之自我确认，令学者当下跳出五蕴牢笼。",
