    "answer": "无为法指不依因缘造作、不生不灭之理体。前五种乃借不同断证状态显现的无为相，最终归结于‘真如无为’——即一切万法之真实本性。禅宗直下明心见性，所证得者即是此不生不灭之真如无为法性。",
