    "answer": "世亲菩萨证明心识生起时不仅能缘外境（见分缘相分），更能自知自照（自证分）。禅修中之所以能够反观‘我在起妄念’、‘念佛是谁’，正是依仗自证分之本觉灵光，为禅宗返观自性提供了严密唯识量论依据。",
