    "question": "超宗和尚常言‘古镜未磨，如何鉴物？磨后如何？’这一古镜之喻对观照自心有何实修指引？",
    "answer": "古镜喻指每个凡夫本具但被妄尘遮盖的自性清净心。‘古镜未磨’是行者尚在无明烦恼中，虽具照耀功能却昏暗不见；‘古镜磨后’喻指行者经闻思参究彻底破除知见障垢，明照森罗万象。然而超宗禅师的极则在于破除‘磨镜之执’：若执着于磨镜修持，心仍未空；直须悟得‘自心非镜，亦无尘可染’，如虚空之映万象，来无所来，去无所去，才是超宗禅师的本怀。",
