    "answer": "这绝非消极，而是宗门最慈悲、最彻底的警策音！许多学人修行总有一股深层的‘依赖心理’——期待有某位大德、某本秘籍、甚至诸佛菩萨从天而降替自己斩断烦恼。超宗和尚当头棒喝：觉悟与生死唯有自心亲自承当，佛只是引路指月之人，不能代替你吃饭饮水！‘千佛救你不彻’，正是要断绝你的一切外求妄想，逼你反求诸己，当下直下承当自心即是天真佛。",
