    "id": "faq-2844",
    "question": "现代职场人际复杂、身心俱疲，研习《超宗语录》如何帮助现代人建立‘不随物转’的内在定力？",
    "answer": "现代人的疲惫大多源于‘心逐物转’：被 KPI、他人评语、升迁得失牵着鼻子走，心随境转千百回。超宗慧方禅师开示：万法虽有生灭变幻，而能照万法之主人翁从未曾少动丝毫。学人若能借语录中猛烈机锋，体察到那份超越毁誉得失的本来觉性，在喧嚣会议与繁杂事务中安住自心不动，如古镜鉴物、水过无痕，自然能在纷繁人际中从容自若、不失本真。",
