    "question": "龙树菩萨造《宝行王正论》，为何在深奥般若中开出针对国王治国与世间福德的广大教法？",
    "answer": "这正体现了大乘菩萨道‘悲智双运、即俗即真’的圆融本怀。龙树菩萨深知：若只讲第一义空，世间君王与大众容易落入断灭见或以为佛法远离人间。因此他以无上智慧为导归，从世间人伦、政治治国、赈济贫乏、戒杀爱民讲起，阐明世间良政与出世解脱乃是阶梯与极则的关系。以般若空慧治国，则政清民乐；以仁政积累福德，则菩提资粮丰足，构成了大乘人间佛教的无上典范。",
