    "id": "faq-2848",
    "question": "《宝行王正论》强调‘信智二根并重’，在当今信息泛滥的时代，如何做到‘因智生信、由信启智’？",
    "answer": "无智之信，流于迷信盲从，极易被邪知邪见与伪师所诱惑；无信之智，流于干慧浮辩，狂妄无根，遇逆境便心溃神散。龙树菩萨主张信智双运：以正智闻思如来经论，深察缘起性空、因果不爽之谛理，由此生起摧扑不倒之清净‘智信’；再以此真实信心为根基，深潜实修，直取离分别妄念的现量实相‘胜智’。二者如车之两轮，相辅相成。",
    "relatedBooks": ["baoxingwangzhenglun","xinxinming"]
