    "question": "《宝行王正论》中关于破除身见、观身不净的论述极其彻底，在日常修行中如何运用此观对治贪欲？",
    "answer": "凡夫贪爱，首在贪恋自身与异性色身，执为美妙常乐，从而引发无尽烦恼争斗。龙树在论中剖解人身三十六物，发毛爪齿、脓血屎尿，剖析无遗，指出其本质无非是一具行尸走肉。修习观身不净不是消极厌世，而是撕下世俗虚幻美化之滤镜，看清感官欲望的无常败坏本质。识得此幻，狂执贪爱自然冰消瓦解，当下能以清净无著之身心投入自利利他之大业。",
    "relatedBooks": ["baoxingwangzhenglun","sixingguan"]
