    "answer": "东晋南北朝时期，中原佛学深受玄学老庄‘贵无’思想影响，学者往往把‘般若性空’错认为老庄的‘虚无之无’，流于谈玄放浪。僧叡亲笔作序，盛赞《十二门论》之译出犹如红日破暗。它清晰分辨了‘缘起性空’与‘老庄虚无’的本质鸿沟，阐明缘起即空、空即缘起之中道，不仅拯救了当时北方狂妄浮靡的清谈学风，更为后来三论宗与禅宗的诞生奠定了坚实义学根基。",
