    "id": "faq-2857",
    "question": "现代人常常被焦虑、执着与心理内耗所折磨，如何运用《十二门论》的‘无作者观’化解心理创伤？",
    "answer": "心理内耗与创伤的核心，往往在于心内紧抓着一个‘受害的自我’或‘失败的我’（作者与受者执）。《十二门论·观作者门》精辟开示：唯有五蕴因缘之迁流和合，根本没有一个永恒不变的‘我’在承受创伤，亦没有一个固定自性的‘外部命运’在施害。照见一切心理苦受皆如梦幻泡影、生灭不停且本体了不可得，心执一放，绑架自我的枷锁应声碎裂，当下重获澄明与自由。",
