    "question": "禅师颂古“狗子佛性无，铁船水上浮”如何超越世俗逻辑知解？",
    "answer": "世间常识认为：狗子是有情生命，理当有佛性；铁船重达千钧，遇水必然沉没。赵州从谂禅师答“无”，正是硬生生截断这种世俗因果逻辑推度。子益禅师颂“铁船水上浮，顺风帆未挂，已过洞庭湖”，以不可思议的超常胜境打破学人脑中的分别格套：参透了这个“无”字，就如同千斤重担顿化清风，无需假借后天技巧帆篷，心光早已直透重重关隘。此非反常理，而是直超言诠意根之无分别智现量境界。",
