    "id": "faq-2921",
    "question": "灵云见桃花悟道，子益禅师为何却云“直饶真到不疑地，放下更参三十年”？",
    "answer": "灵云志勤禅师参禅三十年未得彻悟，一日见桃花盛开忽然大悟，作偈曰“三十年来寻剑客，几回落叶又抽枝；自从一见桃花后，直至如今更不疑”。寻常人至此便以为功德圆满、大功告成，子益禅师却施以宗门险峻一拶：“直饶真到不疑地，放下更参三十年！”这正是杨岐派防范后学“稍有省发便生自满、滞于见境”的严厉钳锤。初悟虽见桃花无染，若不彻底放下悟境历境大炼，仍易被微细理障所缠，必须悟后起修、炼至圆熟无痕方为真归宿。",
