    "id": "faq-2923",
    "question": "语录中“兴化三门开两边，聚头噇饭不谈禅”展现了怎样的生活禅境界？",
    "answer": "子益禅师在兴化寺开堂时作诗偈云：“兴化三门开两边，聚头噇饭不谈禅。天童有问其中事，收割今年胜去年。”这绝非庸俗懈怠，而是宗门返璞归真的极高境界！大门任人往来，肚子饿了就坦荡大口吃饭（噇饭），绝不在饭桌上故弄玄虚谈玄说妙；邻寺高僧来勘验宗风，答以田野稻谷丰收。这生动地体现了禅宗“佛法在日用处，饥来吃饭困来眠”的真髓——道不远人，不离耕作生息，当下无造作、无矫揉，便是无上清净道场。",
