    "id": "faq-2925",
    "question": "现代行者如何在充满功利与焦虑的环境中借“剑关”机锋斩断内心葛藤？",
    "answer": "现代人常陷于内外焦虑与思维反刍的痛苦中，心理学称之为“过度思考”。剑关子益禅师的“长剑倚天”正是最辛辣的解药：第一，学会“截断众流”，当杂念妄想如潮水般涌来时，提撕起自心觉照，如利剑当空一挥，当下不随妄念转动；第二，体认“全收全放”，在工作中专注尽责（放得开），在闲暇时归于宁静自足（收得住），不让得失利害牵着鼻子走；第三，安住“平常日用”，吃饭时专心吃饭，行走时专心行走，把心带回当下的每一个呼吸，即是向剑刃之下绝处逢生、顿见本来。",
