    "question": "断桥妙伦禅师在南宋临济杨岐派传承中具有怎样的历史地位？",
    "answer": "断桥妙伦禅师是南宋晚期临济宗杨岐派破庵法脉的核心中坚，师承一代大宗师径山无准师范，与西岩了慧、雪岩祖钦鼎足而立，合称杨岐三大巨宿。他历主瑞峰、瑞岩、天台国清，晚年主江南五山名刹杭州净慈寺，以峻烈雄健的宗风整饬丛林，门下海内外弟子云集，尤其对东瀛日本禅僧影响深远，是宋元禅宗法脉流播东亚的关键桥梁。",
