    "answer": "“断桥”既是妙伦禅师的别号，也是其核心宗风的象征。世间的桥梁用来渡人过河，必须有桥脚支撑、有规整台阶；而宗门参究旨在破除一切依赖与阶级阶梯。“断桥无脚，步步通霄”寓意着参禅者唯有断尽一切思维阶梯、断绝向外攀缘的依赖退路，才能在无依无伴的绝境中彻底自悟自立，脚踏大虚空，走出真正的活路。",
