    "question": "傅大士在禅宗史上具有怎样的特殊地位？为何被尊为弥勒化身与梁代三大士？",
    "answer": "南朝梁代善慧大士傅翕（497－569）与菩提达摩、宝志禅师并称‘梁代三大士’。大士虽示现在家白衣，却具足无师智与出世大解脱，得首楞严三昧；在双林树下结庵修道、鬻妻子救度饥民、见梁武帝挥案拍桌讲经，开创了禅宗大机大用与居士实修之先河。其名著《心王铭》《还源诗》《行路难》为后世禅宗直指人心、见性成佛提供了最重要的心性论基石，因此被禅宗世代公认为弥勒菩萨应身示迹。",
