    "question": "《丛林校定清规总要》在禅门清规发展史中具有怎样的枢纽地位？",
    "answer": "本书由南宋金华后湖比丘惟勉于咸淳十年（1274年）编次，是唐宋清规与元明清规之间不可或缺的承前启后之作。自唐代百丈创制、北宋崇宁清规与《禅苑清规》（1103年）之后，本书博采宋末各刹异本、去粗取精，首次绘制僧堂十六板首图与四节茶汤位次图，确立了两班职事规制，成为后来元代《禅林备用清规》与《敕修百丈清规》直接依据的蓝本母本。",
