    "answer": "自性本来清净平等、法尔如是，本无圣凡之差与言教之迹（法尔不尔）；然世人往往迷己逐物，故祖师不得不垂慈施设方便建立指南。正因为自性从来没有虚妄造作，所以这无为自然的法尔本性，正是最为真实究竟的修行指南！若于自性法尔之外另觅玄妙指南，便是头上安头、背道而驰。",
