    "answer": "雪窦重显以颂古诗偈名满天下，临终却以‘患语之多’作最后开示，此乃大宗师洗尽铅华、向道友门人表露‘不可死于文字句下’之至真悲心；而其从容指点塔所、散赠衣盂、预记期日，至期侧卧安详而逝，全无丝毫凡俗生死眷恋恐惧，展现了宗门大彻悟者出入生死、去留自如的解脱境界。",
