    "answer": "现代人信息充塞，研读公案极易落入知解思辨之泥潭。雪窦宗风警策我们：阅读公案语录不可在字句字面义理上推敲琢磨，须学会‘向言前领旨’。当看到宗师的问答机锋时，应当借其言语反观当下能看能听、一念不生的自心自性。只要自心放下攀缘知见，便能与千年前雪窦和尚顶门相照，不被万卷文字所转。",
