    "answer": "《禅林备用清规》是禅宗四大清规（宋代《禅苑清规》、《丛林校定清规总要》、元代《备用清规》、《敕修百丈清规》）承前启后的关键枢纽。宋末元初丛林制度发生诸多变迁，旧制或讹或失。东林泽山一咸历三十年博访江南诸刹，详订沿革损益，撰集此书。它直接成为元顺帝敕命东村德辉编修《敕修百丈清规》最主要的底本依据，具有承先启后的里程碑价值。",
