    "answer": "修上座向雪岩传授的心法，直击禅僧做工夫散漫软弱之通病。‘高着蒲团’使骨盆与腰椎自然形成前倾稳固支撑，重心落于丹田；‘竖起脊梁，教他节节相拄’使整条脊柱如生铁相咬相顶，中轴笔挺不歪不斜，气脉畅通无阻；不仅从生理上杜绝了因含胸驼背带来的昏沉昏睡，更从心理上唤醒了‘一人与万人敌’之英雄魄力。身端则气定，气定则心坚，如此调身调心，方能为深沉浩瀚的疑情提摄提供坚不可摧的物质依托。",
