    "answer": "第二种病最为普遍：学人未能破参，仅凭六根觉受体会到一点眼耳清醒、灵敏知觉（昭昭灵灵），就误以为见到了临济宗所谓的‘无位真人’；在扬眉瞬目、弄拳竖指间玩弄小聪明。世宗直斥这纯粹是在生死识神窠臼里讨生活，犹如日下点孤灯、含生铁丸自称琼浆，大难临头时依旧是茫茫无据随业轮转。",
