    "answer": "第三种病是末法丛林之痞棍。自己毫无真实悟证工夫，专门在祖师经教语录中抄摘奇言妙句，窃取前人机锋唾余；向人前搬弄是非、谈玄说妙，以此博取名闻利养与法师高位。世宗痛批其为‘盲驴牵盲驴，绕磨盘而转’，欺心欺佛，招引阿鼻地狱之恶果。",
